def is_valid_star(grid, x, y, size):
    n = len(grid)
    m = len(grid[0])
    if x - size < 0 or x + size >= n or y - size < 0 or y + size >= m:
        return False
    for i in range(x - size, x + size + 1):
        for j in range(y - size, y + size + 1):
            if abs(i - x) + abs(j - y) == size and grid[i][j] == '*':
                continue
            elif grid[i][j] == '*':
                return False
    return True

def place_stars(grid):
    n = len(grid)
    m = len(grid[0])
    stars = []
    visited = [[False] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*' and not visited[i][j]:
                size = 1
                while is_valid_star(grid, i, j, size):
                    stars.append((i + 1, j + 1, size))
                    for x in range(i - size, i + size + 1):
                        for y in range(j - size, j + size + 1):
                            if abs(x - i) + abs(y - j) == size:
                                visited[x][y] = True
                    size += 1

    return stars

